import re

def check_password_strength(password: str) -> str:
    # Check if password length is between 8 and 20
    if not 8 <= len(password) <= 20:
        return "Weak"

    # Initialize a counter for the number of missing criteria
    missing_criteria = 0

    # Check if password contains at least one uppercase letter
    if not re.search(r"[A-Z]", password):
        missing_criteria += 1

    # Check if password contains at least one lowercase letter
    if not re.search(r"[a-z]", password):
        missing_criteria += 1

    # Check if password contains at least one digit
    if not re.search(r"\d", password):
        missing_criteria += 1

    # Check if password contains at least one special character
    if not re.search(r"[!@#$%^&*()_-]", password):
        missing_criteria += 1

    # If password misses one criterion, it is moderate
    if missing_criteria == 1:
        return "Moderate"
    # If password misses two or more criteria, it is weak
    elif missing_criteria >= 2:
        return "Weak"
    # If password passes all checks, it is strong
    else:
        return "Strong"

