def balancedParenthesesAndSum(expression):
    stack = []
    sum = 0
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return -1
            stack.pop()
        elif char.isdigit():
            sum += int(char)
    if stack:
        return -1
    return sum

