def analyze_data_transfers(transfers: List[Tuple[str, str, int]]) -> List[Tuple[str, int]]:
    # 使用字典来存储每个源IP的总数据传输量
    total_transfers = {}
    for source, _, data_amount in transfers:
        if source in total_transfers:
            total_transfers[source] += data_amount
        else:
