def unique_sorted_words(inputfile: str, outputfile: str) -> bool:
    try:
        with open(inputfile, 'r') as f_in, open(outputfile, 'w') as f_out:
            # 读取每行的句子并将它们存储在集合中
            unique_words = set()
            for line in f_in:
                words = line.split()
                for word in words:
                    unique_words.add(word.lower())
            # 将集合中的单词按字母顺序排序并写入输出文件
            sorted_words = sorted(list(unique_words))
            for word in sorted_words:
                f_out.write(word + '\n')
        return True
    except Exception as e:
        print(f"Error: {e}")
        return False

