class TrieNode:
    def __init__(self):
        self.children = {}
        self.end_of_word = False

class Solution:
    def find_words(self, s, d):
        root = TrieNode()
        for word in d:
            node = root
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]
            node.end_of_word = True

        def dfs(node, path):
            if node.end_of_word:
                return [path]
            result = []
            for char in s:
                if char in node.children:
                    result.extend(dfs(node.children[char], path + char))
            return result

        return dfs(root, "")

solution = Solution()
print(solution.find_words("listen", ["silent", "enlist", "tinsel"]))

